```java
public static int digitSum(int n) {
    int sum = 0;
    while (n > 0) {
        sum += n % 10;
        n /= 10;
    }
    return sum;
}
```

```java
public static int countDivisible(int lo, int hi, int k) {
    int count = 0;
    for (int x = lo; x <= hi; x++) {
        if (digitSum(x) % k == 0) {
            count++;
        }
    }
    return count;
}
```

```java
public class PunchCard {
    private int remaining;
    private int punches;
    public PunchCard(int visits) {
        remaining = visits;
        punches = 0;
    }
    public boolean punch() {
        if (remaining == 0) {
            return false;
        }
        remaining--;
        punches++;
        if (punches % 5 == 0) {
            remaining++;
        }
        return true;
    }
    public int getRemaining() {
        return remaining;
    }
}
```

